// ============================================================================
// PYTHON FASTAPI BACKEND BRIDGE
// ============================================================================

function isLocalPythonServerHost() {
  const host = window.location.hostname;
  return (host === "localhost" || host === "127.0.0.1") && window.location.protocol.startsWith("http");
}

async function callPythonApi(path, options = {}) {
  if (!isLocalPythonServerHost()) return null;
  try {
    const endpoint = window.location.origin + path;
    const response = await window.fetch(endpoint, {
      headers: { "Content-Type": "application/json" },
      ...options
    });
    if (response.ok) {
      state.pythonBackendConnected = true;
      const badge = document.getElementById("backend-status-text");
      if (badge) badge.textContent = "Connected to FastAPI + SQLite (memosphere.db)";
      return await response.json();
    }
  } catch (err) {
    state.pythonBackendConnected = false;
  }
  return null;
}

async function syncFromPythonBackend() {
  if (!isLocalPythonServerHost()) return;
  const [pRes, plRes, envRes, memRes, aRes, rRes, medRes, remRes] = await Promise.all([
    callPythonApi("/api/people"),
    callPythonApi("/api/places"),
    callPythonApi("/api/environment-guide"),
    callPythonApi("/api/memories"),
    callPythonApi("/api/activities"),
    callPythonApi("/api/routines"),
    callPythonApi("/api/medications"),
    callPythonApi("/api/reminders")
  ]);
  if (pRes && pRes.data) state.people = pRes.data;
  if (plRes && plRes.data) state.places = plRes.data;
  if (envRes && envRes.data) state.environmentGuides = envRes.data;
  if (memRes && memRes.data) state.memories = memRes.data;
  if (aRes && aRes.data) state.activities = aRes.data;
  if (rRes && rRes.data) state.routines = rRes.data;
  if (medRes && medRes.data) state.medications = medRes.data;
  if (remRes && remRes.allReminders) state.reminders = remRes.allReminders;
  renderAll();
}

function loadFromLocalStorage() {
  try {
    const p = localStorage.getItem("memosphere_v2_people");
    const pl = localStorage.getItem("memosphere_v2_places");
    const mem = localStorage.getItem("memosphere_v2_memories");
    const a = localStorage.getItem("memosphere_v2_activities");
    const r = localStorage.getItem("memosphere_v2_routines");
    const med = localStorage.getItem("memosphere_v2_medications");
    const rem = localStorage.getItem("memosphere_v2_reminders");
    if (p) state.people = JSON.parse(p);
    if (pl) state.places = JSON.parse(pl);
    if (mem) state.memories = JSON.parse(mem);
    if (a) state.activities = JSON.parse(a);
    if (r) state.routines = JSON.parse(r);
    if (med) state.medications = JSON.parse(med);
    if (rem) state.reminders = JSON.parse(rem);
  } catch (e) {
    // Ignore storage restriction
  }
}

function saveToLocalStorage() {
  try {
    localStorage.setItem("memosphere_v2_people", JSON.stringify(state.people));
    localStorage.setItem("memosphere_v2_places", JSON.stringify(state.places));
    localStorage.setItem("memosphere_v2_memories", JSON.stringify(state.memories));
    localStorage.setItem("memosphere_v2_activities", JSON.stringify(state.activities));
    localStorage.setItem("memosphere_v2_routines", JSON.stringify(state.routines));
    localStorage.setItem("memosphere_v2_medications", JSON.stringify(state.medications));
    localStorage.setItem("memosphere_v2_reminders", JSON.stringify(state.reminders));
  } catch (e) {
    // Ignore storage restriction
  }
}

// ============================================================================
// SPEECH SYNTHESIS (TTS), VIBRATION & AUDIO CHIME ENGINE
// ============================================================================

function speakTextAloud(text, langOverride) {
  const cleanText = String(text || "").trim();
  if (!cleanText) return;
  state.lastSpokenText = cleanText;

  if ("speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
      const utter = new SpeechSynthesisUtterance(cleanText);
      utter.lang = langOverride || state.voiceLanguage || "en-IN";
      utter.rate = parseFloat(state.voiceSpeed) || 0.9;
      const ind = document.getElementById("voice-state-indicator");
      utter.onstart = () => {
        if (ind) ind.textContent = "🔊 Speaking Response...";
      };
      utter.onend = () => {
        if (ind) ind.textContent = "● Idle (Mic Off — Privacy Protected)";
      };
      window.speechSynthesis.speak(utter);
    } catch (e) {}
  }
}

function stopSpeaking() {
  if ("speechSynthesis" in window) {
    try {
      window.speechSynthesis.cancel();
    } catch (e) {}
  }
  const ind = document.getElementById("voice-state-indicator");
  if (ind) ind.textContent = "● Idle (Mic Off — Privacy Protected)";
}

function playGentleReminderChimeAndVibrate() {
  if ("vibrate" in navigator) {
    try {
      navigator.vibrate([450, 200, 450, 200, 600]);
    } catch (e) {}
  }

  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (AudioCtx) {
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(528, ctx.currentTime);
      osc.frequency.setValueAtTime(660, ctx.currentTime + 0.22);
      gain.gain.setValueAtTime(0.14, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.65);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.68);
    }
  } catch (e) {}
}

function triggerPersistentReminderModal(reminderObj) {
  const rem = reminderObj || state.reminders[0];
  state.activeReminderModalId = rem.id;

  document.getElementById("persistent-rem-priority").textContent =
    "🚨 " + (rem.priority || "CRITICAL").toUpperCase() + " REMINDER — VIBRATING";
  document.getElementById("persistent-rem-time").textContent = rem.scheduledTime || "08:00 AM";
  document.getElementById("persistent-rem-title").textContent = rem.title;

  const overlay = document.getElementById("persistent-reminder-overlay");
  overlay.classList.remove("hidden");
  overlay.classList.add("flex");

  if (state.activeVibrationTimer) {
    clearInterval(state.activeVibrationTimer);
  }
  playGentleReminderChimeAndVibrate();
  speakTextAloud("Reminder: " + rem.title + ". Please tap Acknowledge when done.");
  state.activeVibrationTimer = setInterval(() => {
    playGentleReminderChimeAndVibrate();
  }, 4500);
}

function stopPersistentReminderOverlay() {
  if (state.activeVibrationTimer) {
    clearInterval(state.activeVibrationTimer);
    state.activeVibrationTimer = null;
  }
  if ("vibrate" in navigator) {
    try {
      navigator.vibrate(0);
    } catch (e) {}
  }
  const overlay = document.getElementById("persistent-reminder-overlay");
  overlay.classList.add("hidden");
  overlay.classList.remove("flex");
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

function escapeHtml(str) {
  return String(str ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function formatRelativeTime(isoString) {
  if (!isoString) return "Never";
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return "Recently";
  const diffMins = Math.max(0, Math.floor((Date.now() - d.getTime()) / 60000));
  if (diffMins < 1) return "Just now";
  if (diffMins < 60) return diffMins + (diffMins === 1 ? " min ago" : " mins ago");
  const diffHrs = Math.floor(diffMins / 60);
  if (diffHrs < 24) return diffHrs + (diffHrs === 1 ? " hr ago" : " hrs ago");
  const diffDays = Math.floor(diffHrs / 24);
  return diffDays + (diffDays === 1 ? " day ago" : " days ago");
}

function getInitials(name) {
  const parts = String(name || "").trim().split(/\s+/);
  if (!parts[0]) return "MS";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function showToast(msg) {
  const container = document.getElementById("toast-container");
  const textEl = document.getElementById("toast-message");
  if (!container || !textEl) return;
  textEl.textContent = msg;
  container.classList.remove("hidden");
  container.classList.add("flex");
  clearTimeout(window._toastTimer);
  window._toastTimer = setTimeout(() => {
    container.classList.add("hidden");
    container.classList.remove("flex");
  }, 3600);
}

function classifyBrainDumpText(text) {
  const lower = String(text || "").toLowerCase();
  if (/\b(kept|parked|bike|glasses|bedside|drawer|shelf|backpack|pocket|cupboard|keys|passport|aadhaar|pillar|basement|located|address)\b/.test(lower)) {
    return { targetModule: "places", label: "Places & Item Finder" };
  }
  if (/\b(met|daughter|son|mother|friend|colleague|teammate|mentor|birthday|anniversary|allergic|likes|coffee|ananya|rahul)\b/.test(lower)) {
    return { targetModule: "people", label: "People Memory" };
  }
  if (/\b(every day|daily|routine|habit|gym|study block|bill due|medication time|schedule|8:00|9:00|remind me)\b/.test(lower)) {
    return { targetModule: "routines", label: "Routines & Habits" };
  }
  return { targetModule: "activities", label: "Daily Activity Log" };
}

function parseTimeSlotToMinutes(slot) {
  const m = String(slot || "").trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return 12 * 60;
  let hrs = parseInt(m[1], 10);
  const mins = parseInt(m[2], 10);
  const period = m[3].toUpperCase();
  if (period === "PM" && hrs < 12) hrs += 12;
  if (period === "AM" && hrs === 12) hrs = 0;
  return hrs * 60 + mins;
}

function computeCircleStatus() {
  const shared = state.routines.filter((r) => r.shareWithCircle);
  const now = new Date();
  const currentMins = now.getHours() * 60 + now.getMinutes();
  const completed = [];
  const pending = [];
  const missed = [];

  shared.forEach((r) => {
    if (r.completedToday) {
      completed.push(r);
    } else if (currentMins > parseTimeSlotToMinutes(r.timeSlot) + 30) {
      missed.push(r);
    } else {
      pending.push(r);
    }
  });

  return {
    generatedAt: now.toISOString(),
    circleMonitoringEnabledCount: shared.length,
    summary: {
      completedCount: completed.length,
      pendingCount: pending.length,
      missedCount: missed.length,
      criticalMissedAlert: missed.some((m) => m.priority === "CRITICAL")
    },
    completed,
    pending,
    missed
  };
}

