function renderOrientationCard() {
  const now = new Date();
  const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  const hr = now.getHours();
  let period = "Morning";
  if (hr >= 12 && hr < 17) period = "Afternoon";
  else if (hr >= 17 && hr < 21) period = "Evening";
  else if (hr >= 21 || hr < 5) period = "Night";

  document.getElementById("orientation-period-badge").textContent = "☀️ " + period + " Orientation (Module A2)";
  document.getElementById("orientation-greeting").textContent = "Good " + period + "! Today is " + days[now.getDay()];
  document.getElementById("orientation-date").textContent = now.getDate() + " " + months[now.getMonth()] + " " + now.getFullYear();
  document.getElementById("orientation-clock").textContent = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  document.getElementById("orientation-visit").textContent = state.expectedVisitText;
  document.getElementById("orientation-appt").textContent = state.upcomingApptText;
}

