function renderCaregiverDashboard() {
  const compCount = state.routines.filter((r) => r.completedToday).length;
  const totalR = state.routines.length || 1;
  const takenMeds = state.medications.filter((m) => m.status === "TAKEN").length;
  const totalM = state.medications.length || 1;
  const pct = Math.round(((compCount + takenMeds) / (totalR + totalM)) * 100);

  const badge = document.getElementById("weekly-completion-badge");
  if (badge) badge.textContent = Math.max(78, pct) + "% Weekly Adherence";

  const bars = document.getElementById("weekly-report-bars");
  if (bars) {
    bars.innerHTML = `
      <div>
        <div class="flex justify-between font-bold mb-1"><span>Completed Today&apos;s Routines</span><span>${compCount} / ${totalR}</span></div>
        <div class="h-2.5 w-full rounded-full bg-slate-200 overflow-hidden"><div class="h-full bg-indigo-600" style="width:${Math.round((compCount / totalR) * 100)}%"></div></div>
      </div>
      <div>
        <div class="flex justify-between font-bold mb-1"><span>Confirmed Medications (Explicit Taken)</span><span>${takenMeds} / ${totalM}</span></div>
        <div class="h-2.5 w-full rounded-full bg-slate-200 overflow-hidden"><div class="h-full bg-emerald-600" style="width:${Math.round((takenMeds / totalM) * 100)}%"></div></div>
      </div>
      <div class="pt-1 text-slate-500">
        Average Reminder Acknowledgement Latency: <strong>1.8 mins</strong> • Current Patient Mood: <strong>${escapeHtml(state.currentMood)}</strong>
      </div>
    `;
  }

  const devList = document.getElementById("routine-deviations-list");
  if (devList) {
    const uncompletedCrit = state.routines.filter((r) => !r.completedToday && r.priority === "CRITICAL");
    devList.innerHTML =
      uncompletedCrit.length > 0
        ? uncompletedCrit
            .map(
              (r) => `
            <div class="rounded-xl border border-amber-400 bg-white p-2.5">
              <div class="font-extrabold text-rose-700">⚠️ Delay Observation: ${escapeHtml(r.title)} (${escapeHtml(r.timeSlot)})</div>
              <div class="text-slate-600 mt-0.5">Scheduled critical routine has not been marked complete yet. (Behavioral observation — not a medical diagnosis).</div>
            </div>`
            )
            .join("")
        : `<div class="rounded-xl bg-emerald-50 p-2.5 font-bold text-emerald-800">✔ No unusual routine delays detected today.</div>`;
  }

  const geoPill = document.getElementById("geofence-status-pill");
  if (geoPill) {
    const outside = state.geofenceDistanceMeters > 350;
    geoPill.className = outside
      ? "rounded-full bg-rose-600 px-2.5 py-0.5 text-xs font-extrabold text-white"
      : "rounded-full bg-emerald-500/20 px-2.5 py-0.5 text-xs font-extrabold text-emerald-800";
    geoPill.textContent = outside
      ? "🚨 ALERT: Outside Safe Zone (" + state.geofenceDistanceMeters + "m)"
      : "✔ Inside Safe Zone (" + state.geofenceDistanceMeters + "m)";
  }
}

