function renderApiInspector() {
  const out = document.getElementById("api-json-output");
  if (!out) return;
  let payload = {};
  if (state.selectedApiEndpoint === "/api/routines/status") {
    payload = computeCircleStatus();
  } else if (state.selectedApiEndpoint === "/api/knowledge-search?q=coffee") {
    const q = (state.globalSearch || "coffee").toLowerCase();
    const mp = state.people.filter((p) => p.name.toLowerCase().includes(q) || p.keyFacts.toLowerCase().includes(q));
    const mpl = state.places.filter((pl) => pl.title.toLowerCase().includes(q) || pl.exactLocation.toLowerCase().includes(q));
    const ma = state.activities.filter((a) => a.actionTitle.toLowerCase().includes(q));
    const mr = state.routines.filter((r) => r.title.toLowerCase().includes(q));
    payload = {
      query: q,
      timestamp: new Date().toISOString(),
      totalMatches: mp.length + mpl.length + ma.length + mr.length,
      results: { people: mp, places: mpl, activities: ma, routines: mr }
    };
  } else if (state.selectedApiEndpoint === "/api/people") {
    payload = { success: true, count: state.people.length, data: state.people };
  } else if (state.selectedApiEndpoint === "/api/places") {
    payload = { success: true, count: state.places.length, data: state.places };
  } else if (state.selectedApiEndpoint === "/api/activities") {
    payload = { success: true, count: state.activities.length, data: state.activities };
  } else {
    payload = { success: true, count: state.routines.length, data: state.routines };
  }
  out.textContent = JSON.stringify(payload, null, 2);
}

