function synthesizePatientGroundedAnswer(questionText) {
  const q = String(questionText || "").trim();
  const low = q.toLowerCase();
  const normKey = low.replace(/[^a-z0-9]+/g, " ").trim();
  state.questionRepeatMap[normKey] = (state.questionRepeatMap[normKey] || 0) + 1;
  const repeatCount = state.questionRepeatMap[normKey];

  if (/glasses|spectacles/.test(low)) {
    const gl = state.places.find((p) => p.title.toLowerCase().includes("glasses")) || {
      title: "Reading Glasses",
      exactLocation: "On the bedside table next to the brass lamp"
    };
    if (repeatCount === 1) {
      return `You last saved that your ${gl.title} are "${gl.exactLocation}". Would you like me to show you the Places card? [Source: places#plc_glasses]`;
    }
    return `Your ${gl.title} are "${gl.exactLocation}". Let's look there together. [Source: places#plc_glasses]`;
  }

  if (/bathroom|bedroom|drinking water|walking shoes|where is the/.test(low)) {
    const eg = state.environmentGuides.find((e) => low.includes(e.locationName.toLowerCase()));
    if (eg) return `${eg.spokenPrompt} [Source: environment_guides#${eg.id}]`;
  }

  if (/ananya|coffee|teammate|birthday|nov 12|daughter/.test(low)) {
    const ananya = state.people.find((p) => p.name.toLowerCase().includes("ananya")) || state.people[0];
    if (ananya) {
      return `${ananya.name} (${ananya.relationship}, met at ${ananya.whereMet}): ${ananya.keyFacts}. Important Date: ${ananya.importantDate || "Birthday: Nov 12"}. [Source: people#${ananya.id}]`;
    }
  }

  if (/passport|bike|parked|pillar|keys/.test(low)) {
    const lines = [];
    state.places.forEach((pl) => {
      if (
        (low.includes("passport") && pl.title.toLowerCase().includes("passport")) ||
        ((low.includes("bike") || low.includes("park")) && pl.title.toLowerCase().includes("bike")) ||
        (low.includes("key") && pl.title.toLowerCase().includes("key"))
      ) {
        lines.push(`📍 ${pl.title}: ${pl.exactLocation} (${pl.notes || ""}) [Source: places#${pl.id}]`);
      }
    });
    if (lines.length) return lines.join("\n");
  }

  if (/mysuru|childhood|lalbagh|memory|story|music/.test(low)) {
    const mem = state.memories[0];
    if (mem) return `From your Memory Album (${mem.title}, ${mem.eraOrYear}): ${mem.storyText} Favourite Music: ${mem.favouriteMusic}. [Source: memories#${mem.id}]`;
  }

  if (/vitamin|door|lock|electricity|bill|water|did i|today/.test(low)) {
    return (
      "Today's Confirmed Actions: " +
      state.activities
        .slice(0, 4)
        .map((a) => `"${a.actionTitle}" (${formatRelativeTime(a.loggedAt)})`)
        .join(", ") +
      "."
    );
  }

  return "I checked your saved personal records in SQLite, and that detail has not been saved yet. I never invent memories—would you like to save it now?";
}

async function askMemosphereAi(questionText) {
  const q = String(questionText || "").trim();
  if (!q) return;

  const box = document.getElementById("ai-answer-box");
  const engineEl = document.getElementById("ai-engine-label");
  const textEl = document.getElementById("ai-answer-text");
  box.classList.remove("hidden");
  textEl.textContent = "Retrieving grounded personal records...";

  state.transcriptLog.unshift({ role: "user", text: q });

  const pyRes = await callPythonApi("/api/ai-assistant", {
    method: "POST",
    body: JSON.stringify({ mode: "ask", prompt: q, language: state.voiceLanguage })
  });

  let answer = "";
  if (pyRes && pyRes.answer) {
    engineEl.textContent = "Engine: " + (pyRes.engine || "FastAPI Backend RAG");
    answer = pyRes.answer;
  } else {
    engineEl.textContent = "Engine: Grounded Local SQLite Recall (Repeat-Safe Patient Mode)";
    answer = synthesizePatientGroundedAnswer(q);
  }

  textEl.textContent = answer;
  state.transcriptLog.unshift({ role: "assistant", text: answer });
  renderVoiceTranscript();
  speakTextAloud(answer);
}

function buildVoiceProposal(utterance) {
  const raw = String(utterance || "").trim();
  const low = raw.toLowerCase();

  const mPlace = raw.match(/(?:remember that\s+)?(?:i\s+)?(?:kept|put|left|stored|parked)\s+(?:my\s+)?(.+?)\s+(?:on|in|at|inside|near)\s+(.+?)(?:\.|$)/i);
  if (mPlace || /glasses|bedside|keys|passport|parked/.test(low)) {
    const title = mPlace ? mPlace[1].trim() : "Reading Glasses";
    const loc = mPlace ? mPlace[2].trim() : raw;
    return {
      targetModule: "places",
      categoryLabel: "Places & Item Finder",
      proposedRecord: {
        title: title.charAt(0).toUpperCase() + title.slice(1),
        category: "Physical Item",
        exactLocation: loc,
        notes: "Captured via Voice Memory Assistant",
        isPinned: true
      },
      confirmationPrompt: `Confirm saving "${title}" at location "${loc}" in Places & Item Finder?`,
      spokenConfirmation: `Saved! I will remember that your ${title} is ${loc}.`
    };
  }

  const mPerson = raw.match(/^([A-Z][a-zA-Z\s]+?)\s+is\s+my\s+([a-zA-Z\s]+?)(?:\.|$)/i);
  if (mPerson || /daughter|son|mother|teammate|friend/.test(low)) {
    const name = mPerson ? mPerson[1].trim() : "Ananya";
    const rel = mPerson ? mPerson[2].trim() : "Daughter / Family";
    return {
      targetModule: "people",
      categoryLabel: "People & Familiar Faces",
      proposedRecord: {
        name,
        relationship: "Family",
        whereMet: "Family Circle",
        keyFacts: raw
      },
      confirmationPrompt: `Confirm saving "${name}" (${rel}) in My People Memory?`,
      spokenConfirmation: `Saved! I have recorded that ${name} is your ${rel}.`
    };
  }

  if (/remind me|tomorrow/.test(low)) {
    const clean = raw.replace(/^remind me to\s+/i, "").replace(/\.$/, "");
    return {
      targetModule: "reminders",
      categoryLabel: "Persistent Acknowledgement Reminders",
      proposedRecord: {
        title: clean.charAt(0).toUpperCase() + clean.slice(1),
        category: "Bills/Errands",
        scheduledTime: "10:00 AM",
        priority: "Important",
        repeatIntervalSec: 120,
        snoozeDurationMins: 5,
        escalationWindowMins: 30
      },
      confirmationPrompt: `Confirm scheduling persistent reminder "${clean}" at 10:00 AM?`,
      spokenConfirmation: `I have scheduled a persistent reminder to ${clean} at 10:00 AM.`
    };
  }

  const cleanAct = raw.replace(/^(?:i\s+)?(?:completed|finished)\s+(?:my\s+)?/i, "").replace(/\.$/, "");
  return {
    targetModule: "activities",
    categoryLabel: "Daily Activities & Action Log",
    proposedRecord: {
      actionTitle: cleanAct.charAt(0).toUpperCase() + cleanAct.slice(1),
      category: "Health/Meds",
      notes: "Voice memory capture",
      source: "voice"
    },
    confirmationPrompt: `Confirm logging completed activity "${cleanAct}" to Today's Timeline?`,
    spokenConfirmation: `Logged! I recorded that you completed ${cleanAct}.`
  };
}

function showVoiceProposalForConfirmation(utterance) {
  const proposal = buildVoiceProposal(utterance);
  state.pendingVoiceProposal = proposal;

  document.getElementById("voice-proposal-card").classList.remove("hidden");
  document.getElementById("voice-proposal-module-badge").textContent = proposal.categoryLabel;
  document.getElementById("voice-proposal-prompt").textContent = proposal.confirmationPrompt;
  document.getElementById("voice-proposal-json").textContent = JSON.stringify(proposal.proposedRecord, null, 2);

  state.transcriptLog.unshift({ role: "user", text: utterance });
  state.transcriptLog.unshift({
    role: "assistant",
    text: proposal.confirmationPrompt + " Please tap Confirm & Save below."
  });
  renderVoiceTranscript();
  speakTextAloud(proposal.confirmationPrompt);
}

function triggerVoiceCapture(onResultCallback, fallbackSamples) {
  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;
  const ind = document.getElementById("voice-state-indicator");
  if (ind) ind.textContent = "🎙️ Listening (Explicit Permission Granted)...";

  if (typeof SpeechRec === "function") {
    try {
      const rec = new SpeechRec();
      rec.lang = state.voiceLanguage || "en-IN";
      rec.interimResults = false;
      rec.onresult = (e) => {
        const transcript = e.results?.[0]?.[0]?.transcript || "";
        if (ind) ind.textContent = "⚙️ Processing Speech...";
        if (transcript) {
          onResultCallback(transcript);
          showToast('Voice captured: "' + transcript + '"');
        }
      };
      rec.onerror = () => {
        const sample = fallbackSamples[Math.floor(Math.random() * fallbackSamples.length)];
        onResultCallback(sample);
        showToast('Voice simulated: "' + sample + '"');
      };
      rec.start();
      return;
    } catch (e) {}
  }
  const sample = fallbackSamples[Math.floor(Math.random() * fallbackSamples.length)];
  onResultCallback(sample);
  showToast('Voice captured: "' + sample + '"');
}

