  document.getElementById("brain-dump-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const raw = brainInput.value.trim();
    if (!raw) return;
    const sel = document.getElementById("brain-dump-target").value;
    const target = sel === "auto" ? classifyBrainDumpText(raw).targetModule : sel;

    if (target === "places") {
      const parts = raw.split(/\s*[—–-]\s*/);
      const title = parts.length >= 2 ? parts[0].trim() : raw.slice(0, 40);
      const exactLocation = parts.length >= 2 ? parts.slice(1).join(" — ").trim() : raw;
      const newPlace = {
        id: "plc_" + Date.now(),
        title,
        category: /parked|bike|scooter|pillar/i.test(raw) ? "Parking Spot" : "Physical Item",
        exactLocation,
        notes: "Captured via Memosphere Smart Brain Dump",
        isPinned: true,
        updatedAt: new Date().toISOString()
      };
      state.places.unshift(newPlace);
      await callPythonApi("/api/places", { method: "POST", body: JSON.stringify(newPlace) });
      showToast('Saved "' + newPlace.title + '" to Places & Item Finder!');
    } else if (target === "people") {
      const parts = raw.split(/\s*[—–-]\s*/);
      const bday = raw.match(/\b(birthday\s+[A-Za-z]+\s+\d{1,2})/i);
      const name = parts.length >= 2 ? parts[0].trim() : raw.split(",")[0].trim();
      const keyFacts = parts.length >= 2 ? parts.slice(1).join(", ").trim() : raw;
      const newPerson = {
        id: "per_" + Date.now(),
        name,
        relationship: /teammate|college/i.test(raw) ? "Teammate" : "Family",
        whereMet: "Added via Memosphere Brain Dump",
        keyFacts,
        importantDate: bday ? bday[1] : null,
        avatarUrl: null,
        voicePrompt: `This is ${name}. ${keyFacts}`,
        lastInteraction: new Date().toISOString(),
        createdAt: new Date().toISOString()
      };
      state.people.unshift(newPerson);
      await callPythonApi("/api/people", { method: "POST", body: JSON.stringify(newPerson) });
      showToast('Saved "' + newPerson.name + '" to People Memory!');
    } else if (target === "routines") {
      const newRoutine = {
        id: "rtn_" + Date.now(),
        title: raw,
        timeSlot: "08:00 AM",
        frequency: "Daily",
        priority: /medicine|medication|bill|rent|critical/i.test(raw) ? "CRITICAL" : "NORMAL",
        shareWithCircle: true,
        completedToday: false,
        lastCompletedAt: null,
        streakCount: 0
      };
      state.routines.unshift(newRoutine);
      await callPythonApi("/api/routines", { method: "POST", body: JSON.stringify(newRoutine) });
      showToast('Added "' + newRoutine.title + '" to Routines!');
    } else {
      const newAct = {
        id: "act_" + Date.now(),
        actionTitle: raw,
        category: /door|lock|gate/i.test(raw) ? "Home Security" : /vitamin|water|pill/i.test(raw) ? "Health/Meds" : "Personal",
        notes: "Logged via Smart Brain Dump",
        source: "manual",
        loggedAt: new Date().toISOString()
      };
      state.activities.unshift(newAct);
      await callPythonApi("/api/activities", { method: "POST", body: JSON.stringify(newAct) });
      showToast('Logged "' + newAct.actionTitle + '" to Today\'s Timeline!');
    }

    brainInput.value = "";
    renderAll();
  });

